const MAX_UPLOAD_BYTES = 1048576; // 1 MB
const utils = global.get("utils");
const files = msg.payload.files || [];

const transferable = [];
const failed = msg.payload.failed_files || [];

files.forEach(file => {
    if (file.size && file.size > MAX_UPLOAD_BYTES) {
        failed.push({ name: file.name || "ukjent fil", reason: utils.FILE_REASONS.OVERSIZED });
    } else {
        transferable.push(file);
    }
});

msg.payload.files = transferable;
msg.payload.failed_files = failed;

if (transferable.length === 0) {
    return [null, msg];
}

return [msg, null];

/**
 * Checks if the Rayvn entry text contains a URL.
 *
 * URL found: files are silently dropped (sender provided a link alternative).
 * No URL: all files marked as non-transferable — notification fires after POST.
 */
const utils = global.get("utils");
const url_pattern = /(?:https?:\/\/|ftp:\/\/|www\.)\S+/i;
const has_url = msg.payload.text && url_pattern.test(msg.payload.text);
const files = msg.payload.files || [];

if (has_url) {
    msg.payload.files = [];
    return msg;
}

const failed = msg.payload.failed_files || [];

files.forEach(file => {
    failed.push({ name: file.name || "ukjent fil", reason: utils.FILE_REASONS.NON_TRANSFERABLE });
});

msg.payload.files = [];
msg.payload.failed_files = failed;

return msg;

