/**
 * Builds the metadata.files object from the working arrays.
 * Sets null if no file data exists (e.g. Rayvn URL-found path).
 */
const files = msg.payload.files || [];
const failed = msg.payload.failed_files || [];

msg.metadata.files = (files.length > 0 || failed.length > 0)
    ? { items: files, failed: failed }
    : null;

return msg;
